  /// An optional finalizer for env
  external ffi.Pointer<
    ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void>)>
  >
  finalizer;

  static ffi.Pointer<wasmtime_stack_memory_t> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Void> env,
    required wasmtime_stack_memory_get_callback_t get_stack_memory,
    required ffi.Pointer<
      ffi.NativeFunction<ffi.Void Function(ffi.Pointer<ffi.Void>)>
    >
    finalizer,
  }) => $allocator<wasmtime_stack_memory_t>()
    ..ref.env = env
    ..ref.get_stack_memory = get_stack_memory
    ..ref.finalizer = finalizer;
}

