  static ffi.Pointer<wasmtime_structref> $allocate(
    ffi.Allocator $allocator, {
    required int store_id,
    required int privateData1,
    required int privateData2,
    required ffi.Pointer<ffi.Void> privateData3,
  }) => $allocator<wasmtime_structref>()
    ..ref.store_id = store_id
    ..ref.privateData1 = privateData1
    ..ref.privateData2 = privateData2
    ..ref.privateData3 = privateData3;
}

typedef wasmtime_structref_t = wasmtime_structref;

/// \brief Representation of a table in Wasmtime.
///
/// Tables in Wasmtime are represented as an index into a store and don't
/// have any data or destructor associated with the #wasmtime_table_t value.
/// Tables cannot interoperate between #wasmtime_store_t instances and if the
/// wrong table is passed to the wrong store then it may trigger an assertion
/// to abort the process.
final class wasmtime_table extends ffi.Struct {
  external UnnamedStruct unnamed;

  /// Private field for Wasmtime.
  @ffi.Uint32()
  external int privateData2;
}

typedef wasmtime_table_t = wasmtime_table;

/// \brief Representation of a tag in Wasmtime.
///
/// Tags in Wasmtime are represented as an index into a store and don't
/// have any data or destructor associated with the #wasmtime_tag_t value.
/// Tags cannot interoperate between #wasmtime_store_t instances and if the
/// wrong tag is passed to the wrong store then it may trigger an assertion
/// to abort the process.
final class wasmtime_tag extends ffi.Struct {
  external UnnamedStruct$2 unnamed;

  /// Private field for Wasmtime.
  @ffi.Uint32()
  external int privateData2;
}

typedef wasmtime_tag_t = wasmtime_tag;

/// \brief Trap codes for instruction traps.
enum wasmtime_trap_code_enum {
  /// The current stack space was exhausted.
  WASMTIME_TRAP_CODE_STACK_OVERFLOW(0),

  /// An out-of-bounds memory access.
  WASMTIME_TRAP_CODE_MEMORY_OUT_OF_BOUNDS(1),

  /// A wasm atomic operation was presented with a not-naturally-aligned
  /// linear-memory address.
  WASMTIME_TRAP_CODE_HEAP_MISALIGNED(2),

  /// An out-of-bounds access to a table.
  WASMTIME_TRAP_CODE_TABLE_OUT_OF_BOUNDS(3),

  /// Indirect call to a null table entry.
  WASMTIME_TRAP_CODE_INDIRECT_CALL_TO_NULL(4),

  /// Signature mismatch on indirect call.
  WASMTIME_TRAP_CODE_BAD_SIGNATURE(5),

  /// An integer arithmetic operation caused an overflow.
  WASMTIME_TRAP_CODE_INTEGER_OVERFLOW(6),

  /// An integer division by zero.
  WASMTIME_TRAP_CODE_INTEGER_DIVISION_BY_ZERO(7),

  /// Failed float-to-int conversion.
  WASMTIME_TRAP_CODE_BAD_CONVERSION_TO_INTEGER(8),

  /// Code that was supposed to have been unreachable was reached.
  WASMTIME_TRAP_CODE_UNREACHABLE_CODE_REACHED(9),

  /// Execution has potentially run too long and may be interrupted.
  WASMTIME_TRAP_CODE_INTERRUPT(10),

  /// Execution has run out of the configured fuel amount.
  WASMTIME_TRAP_CODE_OUT_OF_FUEL(11),

  /// Used to indicate that a trap was raised by atomic wait operations on non
  /// shared memory.
  WASMTIME_TRAP_CODE_ATOMIC_WAIT_NON_SHARED_MEMORY(12),

  /// Call to a null reference.
  WASMTIME_TRAP_CODE_NULL_REFERENCE(13),

  /// Attempt to access beyond the bounds of an array.
  WASMTIME_TRAP_CODE_ARRAY_OUT_OF_BOUNDS(14),

  /// Attempted an allocation that was too large to succeed.
  WASMTIME_TRAP_CODE_ALLOCATION_TOO_LARGE(15),

  /// Attempted to cast a reference to a type that it is not an instance of.
  WASMTIME_TRAP_CODE_CAST_FAILURE(16),

  /// When the `component-model` feature is enabled this trap represents a
  /// scenario where one component tried to call another component but it
  /// would have violated the reentrance rules of the component model,
  /// triggering a trap instead.
  WASMTIME_TRAP_CODE_CANNOT_ENTER_COMPONENT(17),

  /// Async-lifted export failed to produce a result by calling `task.return`
  /// before returning `STATUS_DONE` and/or after all host tasks completed.
  WASMTIME_TRAP_CODE_NO_ASYNC_RESULT(18),

  /// We are suspending to a tag for which there is no active handler.
  WASMTIME_TRAP_CODE_UNHANDLED_TAG(19),

  /// Attempt to resume a continuation twice.
  WASMTIME_TRAP_CODE_CONTINUATION_ALREADY_CONSUMED(20),

  /// A Pulley opcode was executed at runtime when the opcode was disabled at
  /// compile time.
  WASMTIME_TRAP_CODE_DISABLED_OPCODE(21),

  /// Async event loop deadlocked; i.e. it cannot make further progress given
  /// that all host tasks have completed and any/all host-owned stream/future
  /// handles have been dropped.
  WASMTIME_TRAP_CODE_ASYNC_DEADLOCK(22),

  /// When the `component-model` feature is enabled this trap represents a
  /// scenario where a component instance tried to call an import or intrinsic
  /// when it wasn't allowed to, e.g. from a post-return function.
  WASMTIME_TRAP_CODE_CANNOT_LEAVE_COMPONENT(23),

  /// A synchronous task attempted to make a potentially blocking call prior
  /// to returning.
  WASMTIME_TRAP_CODE_CANNOT_BLOCK_SYNC_TASK(24),

  /// A component tried to lift a `char` with an invalid bit pattern.
  WASMTIME_TRAP_CODE_INVALID_CHAR(25),

  /// Debug assertion generated for a fused adapter regarding the expected
  /// completion of a string encoding operation.
  WASMTIME_TRAP_CODE_DEBUG_ASSERT_STRING_ENCODING_FINISHED(26),

  /// Debug assertion generated for a fused adapter regarding a string
  /// encoding operation.
  WASMTIME_TRAP_CODE_DEBUG_ASSERT_EQUAL_CODE_UNITS(27),

  /// Debug assertion generated for a fused adapter regarding the alignment of
  /// a pointer.
  WASMTIME_TRAP_CODE_DEBUG_ASSERT_POINTER_ALIGNED(28),

  /// Debug assertion generated for a fused adapter regarding the upper bits
  /// of a 64-bit value.
  WASMTIME_TRAP_CODE_DEBUG_ASSERT_UPPER_BITS_UNSET(29),

  /// A component tried to lift or lower a string past the end of its memory.
  WASMTIME_TRAP_CODE_STRING_OUT_OF_BOUNDS(30),

  /// A component tried to lift or lower a list past the end of its memory.
  WASMTIME_TRAP_CODE_LIST_OUT_OF_BOUNDS(31),

  /// A component used an invalid discriminant when lowering a variant value.
  WASMTIME_TRAP_CODE_INVALID_DISCRIMINANT(32),

  /// A component passed an unaligned pointer when lifting or lowering a
  /// value.
  WASMTIME_TRAP_CODE_UNALIGNED_POINTER(33),

  /// `task.cancel` invoked in an invalid way.
  WASMTIME_TRAP_CODE_TASK_CANCEL_NOT_CANCELLED(34),

  /// `task.cancel` or `task.return` called too many times
  WASMTIME_TRAP_CODE_TASK_CANCEL_OR_RETURN_TWICE(35),

  /// `subtask.cancel` invoked after it already finished.
  WASMTIME_TRAP_CODE_SUBTASK_CANCEL_AFTER_TERMINAL(36),

  /// `task.return` invoked with an invalid type.
  WASMTIME_TRAP_CODE_TASK_RETURN_INVALID(37),

  /// `waitable-set.drop` invoked on a waitable set with waiters.
  WASMTIME_TRAP_CODE_WAITABLE_SET_DROP_HAS_WAITERS(38),

  /// `subtask.drop` invoked on a subtask that hasn't resolved yet.
  WASMTIME_TRAP_CODE_SUBTASK_DROP_NOT_RESOLVED(39),

  /// `thread.new-indirect` invoked with a function that has an invalid type.
  WASMTIME_TRAP_CODE_THREAD_NEW_INDIRECT_INVALID_TYPE(40),

  /// `thread.new-indirect` invoked with an uninitialized function reference.
  WASMTIME_TRAP_CODE_THREAD_NEW_INDIRECT_UNINITIALIZED(41),

  /// Backpressure-related intrinsics overflowed the built-in counter.
  WASMTIME_TRAP_CODE_BACKPRESSURE_OVERFLOW(42),

  /// Invalid code returned from `callback` of `async`-lifted function.
  WASMTIME_TRAP_CODE_UNSUPPORTED_CALLBACK_CODE(43),

  /// Cannot resume a thread which is not suspended.
  WASMTIME_TRAP_CODE_CANNOT_RESUME_THREAD(44),

  /// Cannot issue a read/write on a future/stream while there is a
  /// pending operation already.
  WASMTIME_TRAP_CODE_CONCURRENT_FUTURE_STREAM_OP(45),

  /// A reference count (for e.g. an `error-context`) overflowed.
  WASMTIME_TRAP_CODE_REFERENCE_COUNT_OVERFLOW(46),

  /// A read/write on a stream must be <2**28 items.
  WASMTIME_TRAP_CODE_STREAM_OP_TOO_BIG(47),

  /// The guest either attempted to add a waitable to a waitable set while it
  /// was being used in a synchronous operation or tried to use it in a
  /// synchronous operation while it was added to a waitable set.
  WASMTIME_TRAP_CODE_WAITABLE_SYNC_AND_ASYNC(48),

  /// An exception propagated out of a component without being caught.
  WASMTIME_TRAP_CODE_UNCAUGHT_EXCEPTION(49),

  /// Guest attempted to read from a stream after being notified that the
  /// writable end was dropped.
  WASMTIME_TRAP_READ_FROM_DROPPED_STREAM(50),

  /// Guest attempted to write to a stream after being notified that the
  /// readable end was dropped.
  WASMTIME_TRAP_WRITE_TO_DROPPED_STREAM(51),

  /// Guest attempted to write to a future after being notified that the
  /// readable end was dropped.
  WASMTIME_TRAP_WRITE_TO_DROPPED_FUTURE(52),

  /// Guest attempted to lift a stream after being notified that the writable
  /// end was dropped.
  WASMTIME_TRAP_LIFT_DROPPED_STREAM(53),

  /// `task.return` or `task.cancel` was called by a task which was not
  /// created by an `async`-lifted export.
  WASMTIME_TRAP_CODE_TASK_RETURN_OR_CANCEL_SYNC_LIFTED(54);

  final int value;
  const wasmtime_trap_code_enum(this.value);

  static wasmtime_trap_code_enum fromValue(int value) => switch (value) {
    0 => WASMTIME_TRAP_CODE_STACK_OVERFLOW,
    1 => WASMTIME_TRAP_CODE_MEMORY_OUT_OF_BOUNDS,
    2 => WASMTIME_TRAP_CODE_HEAP_MISALIGNED,
    3 => WASMTIME_TRAP_CODE_TABLE_OUT_OF_BOUNDS,
    4 => WASMTIME_TRAP_CODE_INDIRECT_CALL_TO_NULL,
    5 => WASMTIME_TRAP_CODE_BAD_SIGNATURE,
    6 => WASMTIME_TRAP_CODE_INTEGER_OVERFLOW,
    7 => WASMTIME_TRAP_CODE_INTEGER_DIVISION_BY_ZERO,
    8 => WASMTIME_TRAP_CODE_BAD_CONVERSION_TO_INTEGER,
    9 => WASMTIME_TRAP_CODE_UNREACHABLE_CODE_REACHED,
    10 => WASMTIME_TRAP_CODE_INTERRUPT,
    11 => WASMTIME_TRAP_CODE_OUT_OF_FUEL,
    12 => WASMTIME_TRAP_CODE_ATOMIC_WAIT_NON_SHARED_MEMORY,
    13 => WASMTIME_TRAP_CODE_NULL_REFERENCE,
    14 => WASMTIME_TRAP_CODE_ARRAY_OUT_OF_BOUNDS,
    15 => WASMTIME_TRAP_CODE_ALLOCATION_TOO_LARGE,
    16 => WASMTIME_TRAP_CODE_CAST_FAILURE,
    17 => WASMTIME_TRAP_CODE_CANNOT_ENTER_COMPONENT,
    18 => WASMTIME_TRAP_CODE_NO_ASYNC_RESULT,
    19 => WASMTIME_TRAP_CODE_UNHANDLED_TAG,
    20 => WASMTIME_TRAP_CODE_CONTINUATION_ALREADY_CONSUMED,
    21 => WASMTIME_TRAP_CODE_DISABLED_OPCODE,
    22 => WASMTIME_TRAP_CODE_ASYNC_DEADLOCK,
    23 => WASMTIME_TRAP_CODE_CANNOT_LEAVE_COMPONENT,
    24 => WASMTIME_TRAP_CODE_CANNOT_BLOCK_SYNC_TASK,
    25 => WASMTIME_TRAP_CODE_INVALID_CHAR,
    26 => WASMTIME_TRAP_CODE_DEBUG_ASSERT_STRING_ENCODING_FINISHED,
    27 => WASMTIME_TRAP_CODE_DEBUG_ASSERT_EQUAL_CODE_UNITS,
    28 => WASMTIME_TRAP_CODE_DEBUG_ASSERT_POINTER_ALIGNED,
    29 => WASMTIME_TRAP_CODE_DEBUG_ASSERT_UPPER_BITS_UNSET,
    30 => WASMTIME_TRAP_CODE_STRING_OUT_OF_BOUNDS,
    31 => WASMTIME_TRAP_CODE_LIST_OUT_OF_BOUNDS,
    32 => WASMTIME_TRAP_CODE_INVALID_DISCRIMINANT,
    33 => WASMTIME_TRAP_CODE_UNALIGNED_POINTER,
    34 => WASMTIME_TRAP_CODE_TASK_CANCEL_NOT_CANCELLED,
    35 => WASMTIME_TRAP_CODE_TASK_CANCEL_OR_RETURN_TWICE,
    36 => WASMTIME_TRAP_CODE_SUBTASK_CANCEL_AFTER_TERMINAL,
    37 => WASMTIME_TRAP_CODE_TASK_RETURN_INVALID,
    38 => WASMTIME_TRAP_CODE_WAITABLE_SET_DROP_HAS_WAITERS,
    39 => WASMTIME_TRAP_CODE_SUBTASK_DROP_NOT_RESOLVED,
    40 => WASMTIME_TRAP_CODE_THREAD_NEW_INDIRECT_INVALID_TYPE,
    41 => WASMTIME_TRAP_CODE_THREAD_NEW_INDIRECT_UNINITIALIZED,
    42 => WASMTIME_TRAP_CODE_BACKPRESSURE_OVERFLOW,
    43 => WASMTIME_TRAP_CODE_UNSUPPORTED_CALLBACK_CODE,
    44 => WASMTIME_TRAP_CODE_CANNOT_RESUME_THREAD,
    45 => WASMTIME_TRAP_CODE_CONCURRENT_FUTURE_STREAM_OP,
    46 => WASMTIME_TRAP_CODE_REFERENCE_COUNT_OVERFLOW,
    47 => WASMTIME_TRAP_CODE_STREAM_OP_TOO_BIG,
    48 => WASMTIME_TRAP_CODE_WAITABLE_SYNC_AND_ASYNC,
    49 => WASMTIME_TRAP_CODE_UNCAUGHT_EXCEPTION,
    50 => WASMTIME_TRAP_READ_FROM_DROPPED_STREAM,
    51 => WASMTIME_TRAP_WRITE_TO_DROPPED_STREAM,
    52 => WASMTIME_TRAP_WRITE_TO_DROPPED_FUTURE,
    53 => WASMTIME_TRAP_LIFT_DROPPED_STREAM,
    54 => WASMTIME_TRAP_CODE_TASK_RETURN_OR_CANCEL_SYNC_LIFTED,
    _ => throw ArgumentError(
      'Unknown value for wasmtime_trap_code_enum: $value',
    ),
  };
}

/// \brief Code of an instruction trap.
///
/// See #wasmtime_trap_code_enum for possible values.
typedef wasmtime_trap_code_t = ffi.Uint8;
typedef Dartwasmtime_trap_code_t = int;

/// \brief An enum for the behavior before extending the epoch deadline.
typedef wasmtime_update_deadline_kind_t = ffi.Uint8;
typedef Dartwasmtime_update_deadline_kind_t = int;

/// \typedef wasmtime_val_t
/// \brief Convenience alias for #wasmtime_val_t
///
/// \union wasmtime_val
/// \brief Container for different kinds of wasm values.
///
/// Note that this structure may contain an owned value, namely rooted GC
/// references, depending on the context in which this is used. APIs which
/// consume a #wasmtime_val_t do not take ownership, but APIs that return
/// #wasmtime_val_t require that #wasmtime_val_unroot is called to clean up
/// any possible GC roots in the value.
///
/// If you do not unroot the value, *even if you free the corresponding
/// Store*, there will be some memory leaked, because GC roots use a
/// separate allocation to track liveness.
final class wasmtime_val extends ffi.Struct {
  /// Discriminant of which field of #of is valid.
  @wasmtime_valkind_t()
  external int kind;

  /// Container for the extern item's value.
  external wasmtime_valunion_t of;
}

/// \typedef wasmtime_val_raw_t
/// \brief Convenience alias for #wasmtime_val_raw
///
/// \union wasmtime_val_raw
/// \brief Container for possible wasm values.
///
/// This type is used on conjunction with #wasmtime_func_new_unchecked as well
/// as #wasmtime_func_call_unchecked. Instances of this type do not have type
/// information associated with them, it's up to the embedder to figure out
/// how to interpret the bits contained within, often using some other channel
/// to determine the type.
final class wasmtime_val_raw extends ffi.Union {
  /// Field for when this val is a WebAssembly `i32` value.
  ///
  /// Note that this field is always stored in a little-endian format.
  @ffi.Int32()
  external int i32;

  /// Field for when this val is a WebAssembly `i64` value.
  ///
  /// Note that this field is always stored in a little-endian format.
  @ffi.Int64()
  external int i64;

  /// Field for when this val is a WebAssembly `f32` value.
  ///
  /// Note that this field is always stored in a little-endian format.
  @float32_t()
  external double f32;

  /// Field for when this val is a WebAssembly `f64` value.
  ///
  /// Note that this field is always stored in a little-endian format.
  @float64_t()
  external double f64;

  /// Field for when this val is a WebAssembly `v128` value.
  ///
  /// Note that this field is always stored in a little-endian format.
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Uint8> v128;

  /// Field for when this val is a WebAssembly `anyref` value.
  ///
  /// If this is set to 0 then it's a null anyref, otherwise this must be
  /// passed to `wasmtime_anyref_from_raw` to determine the
  /// `wasmtime_anyref_t`.
  ///
  /// Note that this field is always stored in a little-endian format.
  @ffi.Uint32()
  external int anyref;

  /// Field for when this val is a WebAssembly `externref` value.
  ///
  /// If this is set to 0 then it's a null externref, otherwise this must be
  /// passed to `wasmtime_externref_from_raw` to determine the
  /// `wasmtime_externref_t`.
  ///
  /// Note that this field is always stored in a little-endian format.
  @ffi.Uint32()
  external int externref;

  /// Field for when this val is a WebAssembly `exnref` value.
  ///
  /// If this is set to 0 then it's a null exnref, otherwise this must be
  /// passed to `wasmtime_exnref_from_raw` to determine the
  /// `wasmtime_exnref_t`.
  ///
  /// Note that this field is always stored in a little-endian format.
  @ffi.Uint32()
  external int exnref;

  /// Field for when this val is a WebAssembly `funcref` value.
  ///
  /// If this is set to 0 then it's a null funcref, otherwise this must be
  /// passed to `wasmtime_func_from_raw` to determine the `wasmtime_func_t`.
  ///
  /// Note that this field is always stored in a little-endian format.
  external ffi.Pointer<ffi.Void> funcref;
}

typedef wasmtime_val_raw_t = wasmtime_val_raw;
typedef wasmtime_val_t = wasmtime_val;

/// \brief Discriminant stored in #wasmtime_val::kind
typedef wasmtime_valkind_t = ffi.Uint8;
typedef Dartwasmtime_valkind_t = int;

/// \brief A WebAssembly value type.
///
/// Note that this is a parallel representation to `wasm_valtype_t` which
/// is intended to support the entire breadth of WebAssembly that wasmtime
/// supports.
final class wasmtime_valtype extends ffi.Struct {
  /// \brief Discriminant of which value type this is.
  @wasmtime_valtype_kind_t()
  external int kind;

  /// \brief Payload of this value type, only used with
  /// `WASMTIME_VALTYPE_KIND_REF`.
  external wasmtime_reftype_t reftype;
}

/// \brief Discriminant located in `wasmtime_valtype_t.kind`
typedef wasmtime_valtype_kind_t = ffi.Uint8;
typedef Dartwasmtime_valtype_kind_t = int;
typedef wasmtime_valtype_t = wasmtime_valtype;

/// \typedef wasmtime_valunion_t
/// \brief Convenience alias for #wasmtime_valunion
///
/// \union wasmtime_valunion
/// \brief Container for different kinds of wasm values.
///
/// This type is contained in #wasmtime_val_t and contains the payload for the
/// various kinds of items a value can be.
final class wasmtime_valunion extends ffi.Union {
  /// Field used if #wasmtime_val_t::kind is #WASMTIME_I32
  @ffi.Int32()
  external int i32;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_I64
  @ffi.Int64()
  external int i64;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_F32
  @float32_t()
  external double f32;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_F64
  @float64_t()
  external double f64;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_ANYREF
  external wasmtime_anyref_t anyref;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_EXTERNREF
  external wasmtime_externref_t externref;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_EXNREF
  external wasmtime_exnref_t exnref;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_FUNCREF
  ///
  /// Use `wasmtime_funcref_is_null` to test whether this is a null function
  /// reference.
  external wasmtime_func_t funcref;

  /// Field used if #wasmtime_val_t::kind is #WASMTIME_V128
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Uint8> v128;
}

typedef wasmtime_valunion_t = wasmtime_valunion;
